/* 记录第一眼看到比自己高的的人的序号 */
function getHigherIndex(arr) {
  let stack = [];

  let len = arr.length;
  let res = new Array(len).fill(0);

  for (let i = 0; i < len; i++) {
    let ele = arr[i];
    let index = i;

    while (true) {
      if (stack.length === 0) {
        stack.push([ele, index]);
        break;
      }

      let [peekEle, peekIndex] = stack[stack.length - 1];

      if (ele > peekEle) {
        res[peekIndex] = index;
        stack.pop();
      } else {
        stack.push([ele, index]);
        break;
      }
    }
  }

  return res;
}

