#include <stdio.h>
#include <string.h>

#define MAX_SIZE 40000

int stack[MAX_SIZE][2];
int stack_size = 0;

char res[MAX_SIZE * 2];

int main() {
    int n;
    scanf("%d", &n);

    int heights[MAX_SIZE];
    int heights_size = 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &heights[heights_size++]);
    }

    int nextHigher[MAX_SIZE] = {0};

    for (int i = 0; i < n; i++) {
        int h = heights[i];

        while (1) {
            if (stack_size == 0) {
                stack[stack_size][0] = h;
                stack[stack_size][1] = i;
                stack_size++;
                break;
            }

            int peekH = stack[stack_size - 1][0];
            int peekI = stack[stack_size - 1][1];

            if (h > peekH) {
                nextHigher[peekI] = i;
                stack_size--;
            } else {
                stack[stack_size][0] = h;
                stack[stack_size][1] = i;
                stack_size++;
                break;
            }
        }
    }

    for (int i = 0; i < heights_size; i++) {
        char tmp[5];
        sprintf(tmp, "%d", nextHigher[i]);
        strcat(res, tmp);
        strcat(res, " ");
    }

    res[strlen(res) - 1] = '\0';

    puts(res);

    return 0;
}
